// Builds client/live-kit.ts: the vetted runtime inlined into every live frame's srcDoc.
// The frame's CSP blocks remote scripts, so the kit must travel inside the document.
// Run after changing scripts/live-kit/* or upgrading preact/htm; the output is committed
// because registry installs omit dev dependencies.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = path => readFileSync(join(root, path), "utf8");
const css = read("scripts/live-kit/base.css").replace(/\n/g, "");
const preact = read("node_modules/htm/preact/standalone.umd.js").replace(/\/\/# sourceMappingURL=.*$/m, "");
const runtime = read("scripts/live-kit/runtime.js");
const version = JSON.parse(read("node_modules/preact/package.json")).version;
const htm = JSON.parse(read("node_modules/htm/package.json")).version;
// Inline scripts end at the first "</script", so the kit must never contain one.
for (const [name, source] of Object.entries({ preact, runtime, css }))
  if (/<\/script/i.test(source) || /<\/style/i.test(source)) throw new Error(`${name} contains a closing tag.`);
const output = `// Generated by scripts/build-live-kit.mjs. Do not edit.
// Bundles preact ${version} and htm ${htm} (MIT, see NOTICE) with the Theme Studio live runtime.
export const liveKitCss = ${JSON.stringify(css)};
export const liveKitScript = ${JSON.stringify(preact + "\n" + runtime)};
`;
writeFileSync(join(root, "client/live-kit.ts"), output);
console.log(`client/live-kit.ts: ${(output.length / 1024).toFixed(1)} KB`);
